Q: are querySelectorAll and getBoundingClientRect compatible? A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let cursor = document.querySelector('.cursorFollower');

const handleCursor = (e) =&gt; {
    var button = e.target;
    if (button.classList.contains("menutext")) {
      const boundingRect = button.getBoundingClientRect();
      let buttonWidth = boundingRect.width;
      let buttonHeight = boundingRect.height;
      let buttonX = boundingRect.left;
      let buttonY = window.scrollY + boundingRect.top;
      cursor.setAttribute(
        "style",
        `left: ${buttonX}px;top: ${buttonY}px;width: ${buttonWidth}px;height: ${buttonHeight}px; transform: rotate(0deg); border: 1px solid #84c4b5;`
      );
      button.setAttribute(
        "style",
        `color: #84C4B5;`
      );
    } else {
      cursor.setAttribute(
        "style",
        `left: width: 20px; height: 20px; transform: rotate(45deg); border: solid 1px #ffffff;`
      );
      cursor.style.left = e.pageX - 10 + 'px';
      cursor.style.top = e.pageY - 10 + 'px';  
      button.setAttribute(
        "style",
        `color: #ffffff;`
      );
    }
};


document.addEventListener("mousemove", handleCursor);</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>*{
